<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use App\Models\{User,Dog,Need,Donation,AdoptionRequest};
class ShelterTest extends TestCase {
 use RefreshDatabase;
 private function user($role='supporter') { $u=User::factory()->create();$u->forceFill(['role'=>$role])->save();return $u; }
 private function dog() {return Dog::create(['name'=>'Luna','age_text'=>'2 años','sex'=>'hembra','size'=>'mediano','description'=>'Ejemplo de prueba','is_published'=>true]);}
 public function test_public_pages_and_escaping(): void {$d=$this->dog();$d->update(['name'=>'<script>alert(1)</script>']);$this->get('/')->assertOk()->assertSee('&lt;script&gt;',false)->assertDontSee('<script>alert(1)</script>',false);$this->get('/login')->assertOk();$this->get('/privacidad')->assertOk();}
 public function test_roles_block_administration(): void {$this->get('/admin/perros')->assertRedirect('/login');$this->actingAs($this->user())->get('/admin/perros')->assertForbidden();$this->get('/cuidados')->assertForbidden();$this->actingAs($this->user('volunteer'))->get('/cuidados')->assertOk();$this->get('/admin/perros')->assertForbidden();}
 public function test_registration_cannot_assign_admin(): void {$this->post('/registro',['name'=>'Prueba','email'=>'test@example.test','password'=>'UnaClaveSegura123','password_confirmation'=>'UnaClaveSegura123','consent'=>'1','role'=>'admin'])->assertRedirect('/panel');$u=User::first();$this->assertEquals('supporter',$u->role);$this->assertNotEquals('UnaClaveSegura123',$u->password);}
 public function test_admin_crud_and_validation(): void {$this->actingAs($this->user('admin'));$this->post('/admin/perros',[])->assertSessionHasErrors('name');$data=['name'=>'Prueba','age_text'=>'1 año','sex'=>'macho','size'=>'pequeño','description'=>'Ficha de prueba','adoption_status'=>'disponible','is_published'=>1];$this->post('/admin/perros',$data)->assertRedirect();$d=Dog::first();$this->get('/admin/perros/'.$d->id.'/editar')->assertOk();$this->put('/admin/perros/'.$d->id,array_replace($data,['name'=>'Nuevo']))->assertRedirect();$this->assertDatabaseHas('dogs',['name'=>'Nuevo']);$this->delete('/admin/perros/'.$d->id)->assertRedirect();$this->assertDatabaseMissing('dogs',['id'=>$d->id]);
 $n=['title'=>'Alimento','description'=>'Bolsas','quantity'=>5,'priority'=>'alta','status'=>'activa'];$this->post('/admin/necesidades',$n)->assertRedirect();$id=Need::first()->id;$this->put('/admin/necesidades/'.$id,array_replace($n,['quantity'=>9]))->assertRedirect();$this->delete('/admin/necesidades/'.$id)->assertRedirect();
 $a=['type'=>'bienes','description'=>'Mantas','status'=>'pendiente'];$this->post('/admin/aportes',$a)->assertRedirect();$id=Donation::first()->id;$this->put('/admin/aportes/'.$id,array_replace($a,['status'=>'recibida']))->assertRedirect();$this->assertDatabaseHas('donations',['status'=>'recibida']);$this->delete('/admin/aportes/'.$id)->assertRedirect();}
 public function test_adoption_ownership_duplicate_and_review(): void {$dog=$this->dog();$u=$this->user();$this->actingAs($u);$data=['dog_id'=>$dog->id,'housing_type'=>'Casa','experience'=>'Experiencia de cuidado responsable','consent'=>1];$this->post('/adopciones',$data)->assertRedirect();$this->post('/adopciones',$data)->assertSessionHasErrors('dog_id');$request=AdoptionRequest::first();$this->flushSession();$this->actingAs($this->user())->get('/panel')->assertDontSee('Experiencia de cuidado responsable');$this->actingAs($this->user('admin'))->post('/admin/revision/adopcion/'.$request->id,['status'=>'aprobada'])->assertRedirect();$this->assertEquals('adoptado',$dog->fresh()->adoption_status);$this->get('/admin/solicitudes')->assertOk();}
 public function test_supporter_cannot_forge_donation_status(): void {$u=$this->user();$this->actingAs($u)->post('/aportes',['type'=>'bienes','description'=>'Alimento','status'=>'recibida','user_id'=>999])->assertRedirect();$this->assertDatabaseHas('donations',['user_id'=>$u->id,'status'=>'pendiente']);$this->post('/aportes',['type'=>'dinero','description'=>'Aporte','amount'=>-1])->assertSessionHasErrors('amount');}
 public function test_volunteer_approval_and_care(): void {$u=$this->user();$dog=$this->dog();$this->actingAs($u)->post('/voluntariado',['skills'=>'Paseos y limpieza','availability'=>'Sábados'])->assertRedirect();$id=\App\Models\VolunteerApplication::first()->id;$this->actingAs($this->user('admin'))->post('/admin/revision/voluntariado/'.$id,['status'=>'aprobada'])->assertRedirect();$this->assertEquals('volunteer',$u->fresh()->role);$this->actingAs($u->fresh())->post('/cuidados',['dog_id'=>$dog->id,'care_type'=>'paseo','description'=>'Paseo tranquilo','recorded_at'=>date('Y-m-d')])->assertRedirect();$this->assertDatabaseHas('care_records',['user_id'=>$u->id]);}
}

